# TL;DR: Generate the complete documentation index from local files and their headers.
# Status: active; date: 2026-10-19.
"""Generate one index entry per docs file; no application imports or model calls."""
import argparse
from pathlib import Path
from _devtools import ROOT, header, tldr, write_generated


def generate_index(root, folder, check=False):
    lines = [header('Documentation inventory; read only the file needed for the task.',
                    'GENERATED by development/scripts/gen_doc_index.py').rstrip(), '', '# Documentation index', '']
    directory = root / folder
    files = {path for path in directory.rglob('*') if path.is_file() and '.tmp' not in path.relative_to(root).parts}
    files.add(directory / 'INDEX.md')
    for path in sorted(files):
        relative = path.relative_to(directory).as_posix()
        if relative == 'INDEX.md':
            purpose = 'Complete documentation inventory'
        elif relative == 'roadmap/INDEX.md':
            purpose = 'Roadmap summary and status; load only this INDEX by default, detail parts on demand'
        elif relative.startswith('roadmap/'):
            purpose = 'Verbatim historical roadmap detail; open only when routed from roadmap/INDEX.md'
        elif path.suffix == '.md':
            try:
                purpose = tldr(path).rstrip('.')
            except ValueError:
                purpose = next((line.lstrip('#').strip() for line in path.read_text().splitlines()
                                if line.startswith('# ')), path.stem)
        else:
            purpose = f'{path.stem.replace("-", " ")} {path.suffix.lstrip(".")} evidence'
        purpose = purpose.replace('[', '').replace(']', '').replace('|', '/')
        lines.append(f'- [{relative}]({relative}) — {purpose}; read when working on {path.stem.replace("-", " ")}.')
    if len('\n'.join(lines).splitlines()) > 150:
        raise ValueError('INDEX exceeds 150 lines; partition docs before adding files')
    return write_generated(directory / 'INDEX.md', '\n'.join(lines) + '\n', check)


def generate(root, check=False):
    results = [generate_index(root, folder, check) for folder in ('docs', 'development/docs')]
    return all(results)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root', type=Path, default=ROOT)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    raise SystemExit(0 if generate(args.root.resolve(), args.check) else 1)
